"""
JavaScript engine for NCERT Class 5 Mathematics - Chapter 5: Far and Near
"""

js_code = '\n// State variables\nlet currentSlide = 1;\nconst totalSlides = 20;\nlet isSpeaking = false;\nlet currentUtterance = null;\nlet watchdogInterval = null;\nlet currentAudioText = "";\n\n// Voice configuration\nlet selectedVoice = null;\nlet availableVoices = [];\n\n// Sound effects using Web Audio API\nconst audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n\nfunction playSound(type) {\n    if (audioCtx.state === \'suspended\') {\n        audioCtx.resume();\n    }\n    const osc = audioCtx.createOscillator();\n    const gain = audioCtx.createGain();\n    osc.connect(gain);\n    gain.connect(audioCtx.destination);\n    const now = audioCtx.currentTime;\n\n    if (type === \'correct\') {\n        osc.type = \'triangle\';\n        osc.frequency.setValueAtTime(440, now);\n        osc.frequency.exponentialRampToValueAtTime(880, now + 0.2);\n        gain.gain.setValueAtTime(0.2, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25);\n        osc.start(now);\n        osc.stop(now + 0.25);\n    } else if (type === \'incorrect\') {\n        osc.type = \'sawtooth\';\n        osc.frequency.setValueAtTime(260, now);\n        osc.frequency.exponentialRampToValueAtTime(130, now + 0.25);\n        gain.gain.setValueAtTime(0.25, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);\n        osc.start(now);\n        osc.stop(now + 0.3);\n    } else if (type === \'click\') {\n        osc.type = \'sine\';\n        osc.frequency.setValueAtTime(600, now);\n        gain.gain.setValueAtTime(0.1, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.08);\n        osc.start(now);\n        osc.stop(now + 0.08);\n    }\n}\n\n// Pure Indian Male Voices Filter\nfunction isIndianMaleVoice(v) {\n    const name = v.name.toLowerCase();\n    const lang = (v.lang || \'\').toLowerCase();\n    const femaleKeywords = [\n        \'female\', \'woman\', \'girl\', \'lady\', \'zira\', \'aria\', \'jenny\', \'heera\',\n        \'neerja\', \'priya\', \'swara\', \'veena\', \'google us english\',\n        \'google indian english\', \'google uk english female\', \'google हिन्दी\'\n    ];\n    if (femaleKeywords.some(kw => name.includes(kw))) return false;\n\n    const indianMaleKeywords = [\'prabhat\', \'rishi\', \'ravi\', \'pradeep\', \'madhav\', \'karan\', \'mohan\'];\n    if (indianMaleKeywords.some(kw => name.includes(kw))) return true;\n\n    if ((lang.includes(\'en-in\') || lang.includes(\'en_in\')) && !femaleKeywords.some(kw => name.includes(kw))) {\n        if (name.includes(\'male\') || !name.includes(\'google\')) return true;\n    }\n    return false;\n}\n\nfunction isGeneralMaleVoice(v) {\n    const name = v.name.toLowerCase();\n    const lang = (v.lang || \'\').toLowerCase();\n    const femaleKeywords = [\n        \'female\', \'woman\', \'girl\', \'lady\', \'zira\', \'aria\', \'jenny\', \'heera\',\n        \'neerja\', \'priya\', \'swara\', \'veena\', \'google us english\',\n        \'google indian english\', \'google uk english female\', \'google हिन्दी\'\n    ];\n    if (femaleKeywords.some(kw => name.includes(kw))) return false;\n\n    if (name.includes(\'uk english male\') || name.includes(\'male\') || name.includes(\'david\') || name.includes(\'mark\') || name.includes(\'alex\') || name.includes(\'daniel\')) {\n        return true;\n    }\n    return false;\n}\n\nfunction initVoices() {\n    if (!(\'speechSynthesis\' in window)) return;\n    const voices = window.speechSynthesis.getVoices();\n    if (!voices || voices.length === 0) return;\n\n    availableVoices = voices;\n    const voiceSelect = document.getElementById(\'voiceSelect\');\n    if (voiceSelect) {\n        voiceSelect.innerHTML = \'\';\n    }\n\n    let indianMale = voices.find(isIndianMaleVoice);\n    let ukMale = voices.find(v => v.name.toLowerCase().includes(\'google uk english male\'));\n    let generalMale = voices.find(isGeneralMaleVoice);\n\n    if (indianMale) {\n        selectedVoice = indianMale;\n    } else if (ukMale) {\n        selectedVoice = ukMale;\n    } else if (generalMale) {\n        selectedVoice = generalMale;\n    } else {\n        selectedVoice = voices[0];\n    }\n\n    voices.forEach((v, idx) => {\n        const isInd = isIndianMaleVoice(v);\n        const isGenMale = isGeneralMaleVoice(v);\n        const option = document.createElement(\'option\');\n        option.value = idx;\n        let badge = \'\';\n        if (isInd) badge = \' 🇮🇳 [Indian Male Teacher]\';\n        else if (isGenMale) badge = \' 👨 [Male Teacher]\';\n        option.textContent = `${v.name} (${v.lang})${badge}`;\n\n        if (v === selectedVoice) {\n            option.selected = true;\n        }\n        if (voiceSelect) {\n            voiceSelect.appendChild(option);\n        }\n    });\n}\n\nfunction onVoiceChange() {\n    const voiceSelect = document.getElementById(\'voiceSelect\');\n    if (!voiceSelect || !availableVoices.length) return;\n    const idx = parseInt(voiceSelect.value, 10);\n    if (!isNaN(idx) && availableVoices[idx]) {\n        selectedVoice = availableVoices[idx];\n        if (isSpeaking) {\n            stopAudio();\n            playCurrentSlideAudio();\n        }\n    }\n}\n\n// Watchdog keep-alive timer for continuous synthesis\nfunction startWatchdog() {\n    stopWatchdog();\n    watchdogInterval = setInterval(() => {\n        if (isSpeaking && window.speechSynthesis.speaking) {\n            window.speechSynthesis.pause();\n            window.speechSynthesis.resume();\n        }\n    }, 10000);\n}\n\nfunction stopWatchdog() {\n    if (watchdogInterval) {\n        clearInterval(watchdogInterval);\n        watchdogInterval = null;\n    }\n}\n\n// Spoken Classroom Lecture\nfunction playCurrentSlideAudio() {\n    if (!(\'speechSynthesis\' in window)) {\n        alert("Text-to-speech is not supported in this browser.");\n        return;\n    }\n    window.speechSynthesis.cancel();\n    stopWatchdog();\n\n    const slideData = slidesData.find(s => s.id === currentSlide);\n    if (!slideData || !slideData.audio_text) return;\n\n    currentAudioText = slideData.audio_text;\n    currentUtterance = new SpeechSynthesisUtterance(currentAudioText);\n\n    if (selectedVoice) {\n        currentUtterance.voice = selectedVoice;\n    }\n\n    const voiceName = (selectedVoice ? selectedVoice.name : \'\').toLowerCase();\n    const isMale = isIndianMaleVoice(selectedVoice || {}) || isGeneralMaleVoice(selectedVoice || {});\n\n    // Acoustic male resonance\n    currentUtterance.pitch = isMale ? 0.85 : 0.55;\n    currentUtterance.rate = 0.94;\n\n    currentUtterance.onstart = () => {\n        isSpeaking = true;\n        startWatchdog();\n        updateAudioButtonUI(true);\n    };\n\n    currentUtterance.onend = () => {\n        isSpeaking = false;\n        stopWatchdog();\n        updateAudioButtonUI(false);\n    };\n\n    currentUtterance.onerror = (e) => {\n        console.warn("Speech synthesis error or cancelled:", e);\n        isSpeaking = false;\n        stopWatchdog();\n        updateAudioButtonUI(false);\n    };\n\n    window.speechSynthesis.speak(currentUtterance);\n}\n\nfunction stopAudio() {\n    if (\'speechSynthesis\' in window) {\n        window.speechSynthesis.cancel();\n    }\n    isSpeaking = false;\n    stopWatchdog();\n    updateAudioButtonUI(false);\n}\n\nfunction toggleAudio() {\n    if (isSpeaking) {\n        stopAudio();\n    } else {\n        playCurrentSlideAudio();\n    }\n}\n\nfunction updateAudioButtonUI(speaking) {\n    const playIcon = document.getElementById(\'audioPlayIcon\');\n    const pauseIcon = document.getElementById(\'audioPauseIcon\');\n    const audioBtnText = document.getElementById(\'audioBtnText\');\n    const audioPulse = document.getElementById(\'audioPulse\');\n\n    if (speaking) {\n        if (playIcon) playIcon.classList.add(\'hidden\');\n        if (pauseIcon) pauseIcon.classList.remove(\'hidden\');\n        if (audioBtnText) audioBtnText.textContent = \'Pause Lecture\';\n        if (audioPulse) audioPulse.classList.remove(\'hidden\');\n    } else {\n        if (playIcon) playIcon.classList.remove(\'hidden\');\n        if (pauseIcon) pauseIcon.classList.add(\'hidden\');\n        if (audioBtnText) audioBtnText.textContent = \'Listen Lecture\';\n        if (audioPulse) audioPulse.classList.add(\'hidden\');\n    }\n}\n\n// Navigation\nfunction goToSlide(n) {\n    if (n < 1 || n > totalSlides) return;\n    stopAudio();\n    currentSlide = n;\n\n    // Show active slide\n    for (let i = 1; i <= totalSlides; i++) {\n        const el = document.getElementById(`slide-${i}`);\n        if (el) {\n            if (i === currentSlide) {\n                el.classList.remove(\'hidden\');\n            } else {\n                el.classList.add(\'hidden\');\n            }\n        }\n    }\n\n    // Update Counter\n    const counter = document.getElementById(\'slideCounter\');\n    if (counter) counter.textContent = `Slide ${currentSlide} of ${totalSlides}`;\n\n    // Update Progress\n    const progressFill = document.getElementById(\'progressFill\');\n    if (progressFill) {\n        const pct = ((currentSlide - 1) / (totalSlides - 1)) * 100;\n        progressFill.style.width = `${pct}%`;\n    }\n\n    for (let i = 1; i <= totalSlides; i++) {\n        const dot = document.getElementById(`dot-${i}`);\n        if (dot) {\n            if (i === currentSlide) {\n                dot.className = \'w-3 h-3 rounded-full bg-amber-400 ring-2 ring-amber-300 scale-125 transition-all\';\n            } else if (i < currentSlide) {\n                dot.className = \'w-2 h-2 rounded-full bg-emerald-400 hover:bg-emerald-300 cursor-pointer transition-all\';\n            } else {\n                dot.className = \'w-2 h-2 rounded-full bg-slate-600 hover:bg-slate-400 cursor-pointer transition-all\';\n            }\n        }\n    }\n\n    // Terminal Slide Invariant\n    const nextBtn = document.getElementById(\'nextBtn\');\n    const lastSlideNotice = document.getElementById(\'lastSlideNotice\');\n    if (currentSlide === totalSlides) {\n        if (nextBtn) nextBtn.style.display = \'none\';\n        if (lastSlideNotice) lastSlideNotice.classList.remove(\'hidden\');\n    } else {\n        if (nextBtn) nextBtn.style.display = \'inline-flex\';\n        if (lastSlideNotice) lastSlideNotice.classList.add(\'hidden\');\n    }\n\n    const prevBtn = document.getElementById(\'prevBtn\');\n    if (prevBtn) {\n        if (currentSlide === 1) {\n            prevBtn.disabled = true;\n            prevBtn.classList.add(\'opacity-40\', \'cursor-not-allowed\');\n        } else {\n            prevBtn.disabled = false;\n            prevBtn.classList.remove(\'opacity-40\', \'cursor-not-allowed\');\n        }\n    }\n\n    initSlideSimulator(currentSlide);\n    window.scrollTo({ top: 0, behavior: \'smooth\' });\n}\n\nfunction nextSlide() {\n    if (currentSlide < totalSlides) {\n        playSound(\'click\');\n        goToSlide(currentSlide + 1);\n    }\n}\n\nfunction prevSlide() {\n    if (currentSlide > 1) {\n        playSound(\'click\');\n        goToSlide(currentSlide - 1);\n    }\n}\n\n// Checkpoint Interaction\nfunction handleCheckpoint(slideId, cpIdx, optIdx, isCorrect, feedback) {\n    const optionsContainer = document.getElementById(`cp-${slideId}-${cpIdx}-options`);\n    const feedbackBox = document.getElementById(`cp-${slideId}-${cpIdx}-fb`);\n    if (!optionsContainer) return;\n\n    const buttons = optionsContainer.querySelectorAll(\'button\');\n    buttons.forEach((btn, idx) => {\n        btn.disabled = true;\n        if (idx === optIdx) {\n            if (isCorrect) {\n                btn.className = \'w-full text-left p-3 rounded-xl bg-emerald-500/20 border-2 border-emerald-400 text-emerald-200 text-xs font-semibold flex items-center justify-between shadow-lg\';\n                btn.innerHTML += \'<span class="text-emerald-400 font-bold ml-2">✓ Correct</span>\';\n                playSound(\'correct\');\n            } else {\n                btn.className = \'w-full text-left p-3 rounded-xl bg-rose-500/20 border-2 border-rose-400 text-rose-200 text-xs font-semibold flex items-center justify-between shadow-lg\';\n                btn.innerHTML += \'<span class="text-rose-400 font-bold ml-2">✗ Incorrect</span>\';\n                playSound(\'incorrect\');\n            }\n        } else {\n            btn.classList.add(\'opacity-50\');\n        }\n    });\n\n    if (feedbackBox) {\n        feedbackBox.textContent = feedback;\n        feedbackBox.className = `mt-3 p-3 rounded-xl text-xs font-medium border ${isCorrect ? \'bg-emerald-950/70 border-emerald-500/40 text-emerald-200\' : \'bg-rose-950/70 border-rose-500/40 text-rose-200\'}`;\n        feedbackBox.classList.remove(\'hidden\');\n    }\n}\n\n// Mastery Quiz Modal\nfunction handleQuizOption(slideId, qIdx, optIdx, isCorrect) {\n    const optionsContainer = document.getElementById(`quiz-${slideId}-${qIdx}-options`);\n    if (!optionsContainer) return;\n\n    const buttons = optionsContainer.querySelectorAll(\'button\');\n    buttons.forEach((btn, idx) => {\n        btn.disabled = true;\n        if (idx === optIdx) {\n            if (isCorrect) {\n                btn.className = \'w-full text-left p-2.5 rounded-lg bg-emerald-500/20 border border-emerald-400 text-emerald-200 text-xs font-semibold flex items-center justify-between\';\n                btn.innerHTML += \'<span class="text-emerald-400 font-bold">✓</span>\';\n                playSound(\'correct\');\n            } else {\n                btn.className = \'w-full text-left p-2.5 rounded-lg bg-rose-500/20 border border-rose-400 text-rose-200 text-xs font-semibold flex items-center justify-between\';\n                btn.innerHTML += \'<span class="text-rose-400 font-bold">✗</span>\';\n                playSound(\'incorrect\');\n            }\n        } else {\n            btn.classList.add(\'opacity-40\');\n        }\n    });\n\n    const solBtn = document.getElementById(`quiz-${slideId}-${qIdx}-solBtn`);\n    if (solBtn) {\n        solBtn.classList.remove(\'hidden\');\n    }\n}\n\nfunction showQuizSolution(slideId, qIdx) {\n    const slideData = slidesData.find(s => s.id === slideId);\n    if (!slideData || !slideData.quizzes || !slideData.quizzes[qIdx]) return;\n    const q = slideData.quizzes[qIdx];\n\n    const modalTitle = document.getElementById(\'solutionModalTitle\');\n    const modalBody = document.getElementById(\'solutionModalBody\');\n    const modal = document.getElementById(\'solutionModal\');\n\n    if (modalTitle) modalTitle.textContent = `Solution: Question ${qIdx + 1}`;\n    if (modalBody) {\n        modalBody.innerHTML = `\n            <div class="mb-3 font-semibold text-slate-200">${q.question}</div>\n            <div class="p-3 bg-emerald-950/50 border border-emerald-500/40 rounded-xl text-emerald-200 text-xs leading-relaxed mb-3">\n                <span class="font-bold text-emerald-300">Correct Answer:</span> ${q.options[q.correct]}\n            </div>\n            <div class="p-3 bg-slate-800/80 rounded-xl text-slate-300 text-xs leading-relaxed border border-slate-700">\n                <span class="font-bold text-amber-300">Explanation & Rule:</span><br>\n                ${q.solution_html}\n            </div>\n        `;\n    }\n    if (modal) {\n        modal.classList.remove(\'hidden\');\n        playSound(\'click\');\n    }\n}\n\nfunction closeSolutionModal() {\n    const modal = document.getElementById(\'solutionModal\');\n    if (modal) modal.classList.add(\'hidden\');\n}\n\n// ----------------------------------------------------------------------------\n// SIMULATOR LOGIC ENGINES (1 to 16)\n// ----------------------------------------------------------------------------\n\nfunction initSlideSimulator(id) {\n    switch(id) {\n        case 1: s1SelectObject(1); break;\n        case 2: s2SetCm(240); break;\n        case 3: s3Compare(\'456 cm\', 456, \'5 m\', 500); break;\n        case 4: s4Compare(182, 128, \'Statue of Unity\', \'Spring Temple Buddha\'); break;\n        case 5: s5Reset(); break;\n        case 6: s6Reset(); break;\n        case 7: s7SetInterval(500); break;\n        case 8: break; // Route schematic\n        case 9: s9InitRuler(); s9SetMm(6); break;\n        case 10: s10SetDay(3, 15); break;\n        case 11: s11Draw(55, \'5 cm 5 mm\'); break;\n        case 12: break; // Addition machine\n        case 13: break; // Subtraction machine\n        case 14: s14Update(4); break;\n        case 15: break; // Benchmark stacker\n        case 16: s16SetInches(52); break;\n    }\n}\n\n// Sim 1: Choosing Units\nlet s1CurrentObj = 1;\nconst s1Data = {\n    1: { icon: \'🏛️\', title: \'India Gate (New Delhi)\', desc: \'Majestic memorial archway in central Delhi.\', unit: \'m\', val: \'42 m\' },\n    2: { icon: \'🧣\', title: \'Cotton Handkerchief\', desc: \'Square cloth for personal use.\', unit: \'cm\', val: \'25 cm\' },\n    3: { icon: \'🕳️\', title: \'Village Drinking Well\', desc: \'Deep vertical cylindrical water well.\', unit: \'m\', val: \'15 m\' },\n    4: { icon: \'🛣️\', title: \'Highway to Jaipur\', desc: \'National highway connecting major cities.\', unit: \'km\', val: \'260 km\' }\n};\n\nfunction s1SelectObject(id) {\n    s1CurrentObj = id;\n    for (let i = 1; i <= 4; i++) {\n        const btn = document.getElementById(`s1Obj${i}`);\n        if (btn) {\n            if (i === id) btn.className = \'px-2 py-1 bg-amber-500/30 text-amber-200 border border-amber-500/40 rounded text-xs font-bold transition\';\n            else btn.className = \'px-2 py-1 bg-slate-800 text-slate-300 border border-slate-700 rounded text-xs font-bold transition\';\n        }\n    }\n    const d = s1Data[id];\n    const icon = document.getElementById(\'s1Icon\');\n    const title = document.getElementById(\'s1Title\');\n    const desc = document.getElementById(\'s1Desc\');\n    const bestUnit = document.getElementById(\'s1BestUnit\');\n    const readout = document.getElementById(\'s1UnitReadout\');\n\n    if (icon) icon.textContent = d.icon;\n    if (title) title.textContent = d.title;\n    if (desc) desc.textContent = d.desc;\n    if (bestUnit) bestUnit.textContent = `Best Unit: ${d.unit.toUpperCase()} • ~${d.val}`;\n    if (readout) readout.textContent = `${d.title}: ${d.unit} (~${d.val})`;\n    playSound(\'click\');\n}\n\nfunction s1TestUnit(u) {\n    const d = s1Data[s1CurrentObj];\n    if (u === d.unit) {\n        playSound(\'correct\');\n        alert(`Correct! ${d.title} is best measured in ${u.toUpperCase()} (~${d.val}).`);\n    } else {\n        playSound(\'incorrect\');\n        alert(`Try again! ${u.toUpperCase()} is not the most practical unit for ${d.title}.`);\n    }\n}\n\n// Sim 2: Double Number Line Fabric Scale\nfunction s2SetCm(val) {\n    const cm = parseInt(val, 10);\n    const m = (cm / 100).toFixed(2);\n    const wholeM = Math.floor(cm / 100);\n    const remCm = cm % 100;\n\n    const slider = document.getElementById(\'s2Slider\');\n    const sliderVal = document.getElementById(\'s2SliderVal\');\n    const readout = document.getElementById(\'s2DualReadout\');\n    const cursor = document.getElementById(\'s2Cursor\');\n\n    if (slider) slider.value = cm;\n    if (sliderVal) sliderVal.textContent = `${cm} cm`;\n    if (readout) readout.textContent = `${m} m = ${cm} cm (${wholeM} m ${remCm} cm)`;\n\n    if (cursor) {\n        // Map 0 to 500 cm -> 0 to 260 px\n        const x = (cm / 500) * 260;\n        cursor.setAttribute(\'transform\', `translate(${x}, 0)`);\n    }\n}\n\n// Sim 3: Comparing Lengths\nfunction s3Compare(labelA, valA, labelB, valB) {\n    const valADisp = document.getElementById(\'s3ValA\');\n    const valBDisp = document.getElementById(\'s3ValB\');\n    const equivADisp = document.getElementById(\'s3EquivA\');\n    const equivBDisp = document.getElementById(\'s3EquivB\');\n    const symBox = document.getElementById(\'s3SymbolBox\');\n    const exp = document.getElementById(\'s3Explanation\');\n    const readout = document.getElementById(\'s3CompReadout\');\n\n    if (valADisp) valADisp.textContent = labelA;\n    if (valBDisp) valBDisp.textContent = labelB;\n    if (equivADisp) equivADisp.textContent = `= ${valA} cm`;\n    if (equivBDisp) equivBDisp.textContent = `= ${valB} cm`;\n\n    let sym = \'=\';\n    if (valA < valB) sym = \'<\';\n    else if (valA > valB) sym = \'>\';\n\n    if (symBox) symBox.textContent = sym;\n    if (exp) exp.textContent = `Converting both to cm: ${valA} cm ${sym} ${valB} cm. Therefore, ${labelA} ${sym} ${labelB}!`;\n    if (readout) readout.textContent = `${labelA} ${sym} ${labelB} (${valA} cm vs ${valB} cm)`;\n    playSound(\'correct\');\n}\n\n// Sim 4: Tallest Statues\nfunction s4Compare(h1, h2, n1, n2) {\n    const diff = h1 - h2;\n    const badge = document.getElementById(\'s4StatueDiff\');\n    if (badge) badge.textContent = `${n1} (${h1}m) - ${n2} (${h2}m) = ${diff} metres!`;\n    playSound(\'click\');\n}\n\n// Sim 5: Measuring Wheel (Rodometer)\nlet s5Revs = 0;\nfunction s5Roll(meters) {\n    s5Revs += meters;\n    const wheel = document.getElementById(\'s5Wheel\');\n    const counterText = document.getElementById(\'s5CounterText\');\n    const readout = document.getElementById(\'s5WheelReadout\');\n\n    const deg = (s5Revs * 360) % 360;\n    if (wheel) wheel.setAttribute(\'transform\', `translate(-15, 20) rotate(${s5Revs * 120})`);\n    if (counterText) counterText.textContent = `${s5Revs} m`;\n    if (readout) readout.textContent = `Distance: ${s5Revs} Metres (${s5Revs} Wheel Revolutions)`;\n    playSound(\'click\');\n}\nfunction s5Reset() {\n    s5Revs = 0;\n    const wheel = document.getElementById(\'s5Wheel\');\n    const counterText = document.getElementById(\'s5CounterText\');\n    const readout = document.getElementById(\'s5WheelReadout\');\n    if (wheel) wheel.setAttribute(\'transform\', \'translate(-15, 20) rotate(0)\');\n    if (counterText) counterText.textContent = \'0 m\';\n    if (readout) readout.textContent = \'Distance: 0 Metres (0 Revs)\';\n}\n\n// Sim 6: The Kilometre\nlet s6Laps = 0;\nfunction s6AddLap() {\n    s6Laps = (s6Laps + 1) % 6;\n    const lapsVal = document.getElementById(\'s6LapsVal\');\n    const metresVal = document.getElementById(\'s6MetresVal\');\n    const stepsVal = document.getElementById(\'s6StepsVal\');\n    const readout = document.getElementById(\'s6KmReadout\');\n    const runner = document.getElementById(\'s6Runner\');\n\n    const metres = s6Laps * 200;\n    const steps = s6Laps * 400;\n    const km = (metres / 1000).toFixed(1);\n\n    if (lapsVal) lapsVal.textContent = `${s6Laps} / 5 Laps`;\n    if (metresVal) metresVal.textContent = `${metres} m`;\n    if (stepsVal) stepsVal.textContent = `${steps.toLocaleString(\'en-IN\')} steps`;\n\n    if (s6Laps === 5) {\n        if (readout) readout.textContent = "CONGRATULATIONS! 5 Laps = 1,000 Metres = 1 KILOMETRE! 🎉";\n        playSound(\'correct\');\n    } else {\n        if (readout) readout.textContent = `${s6Laps} Laps = ${metres} Metres (${km} km)`;\n        playSound(\'click\');\n    }\n\n    if (runner) {\n        // Move along oval perimeter\n        const pos = [\n            [-80, 0], [-20, -40], [40, -40], [80, 0], [20, 40], [-80, 0]\n        ];\n        const p = pos[s6Laps] || [-80, 0];\n        runner.setAttribute(\'cx\', p[0]);\n        runner.setAttribute(\'cy\', p[1]);\n    }\n}\nfunction s6Reset() {\n    s6Laps = 0;\n    const lapsVal = document.getElementById(\'s6LapsVal\');\n    const metresVal = document.getElementById(\'s6MetresVal\');\n    const stepsVal = document.getElementById(\'s6StepsVal\');\n    const readout = document.getElementById(\'s6KmReadout\');\n    const runner = document.getElementById(\'s6Runner\');\n\n    if (lapsVal) lapsVal.textContent = \'0 / 5\';\n    if (metresVal) metresVal.textContent = \'0 m\';\n    if (stepsVal) stepsVal.textContent = \'0 steps\';\n    if (readout) readout.textContent = \'0 Laps = 0 Metres (0 km)\';\n    if (runner) {\n        runner.setAttribute(\'cx\', -80);\n        runner.setAttribute(\'cy\', 0);\n    }\n}\n\n// Sim 7: Race Track\nfunction s7SetInterval(dist) {\n    const group = document.getElementById(\'s7StationMarkers\');\n    const status = document.getElementById(\'s7CourseStatus\');\n    if (!group) return;\n\n    group.innerHTML = \'\';\n    const numStations = Math.floor(3000 / dist) - 1;\n    // Track length = 280 px (10 to 290)\n    for (let i = 1; i <= numStations; i++) {\n        const markDist = i * dist;\n        const x = 10 + (markDist / 3000) * 280;\n        const circle = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');\n        circle.setAttribute(\'cx\', x);\n        circle.setAttribute(\'cy\', \'0\');\n        circle.setAttribute(\'r\', \'5\');\n        circle.setAttribute(\'fill\', \'#38bdf8\');\n        circle.setAttribute(\'stroke\', \'#ffffff\');\n        circle.setAttribute(\'stroke-width\', \'1.5\');\n        group.appendChild(circle);\n\n        const text = document.createElementNS(\'http://www.w3.org/2000/svg\', \'text\');\n        text.setAttribute(\'x\', x);\n        text.setAttribute(\'y\', i % 2 === 0 ? \'-12\' : \'-22\');\n        text.setAttribute(\'text-anchor\', \'middle\');\n        text.setAttribute(\'font-size\', \'8\');\n        text.setAttribute(\'fill\', \'#7dd3fc\');\n        text.textContent = `${markDist}m`;\n        group.appendChild(text);\n    }\n\n    if (status) status.textContent = `${numStations} Checkpoints Every ${dist}m across 3 km!`;\n    playSound(\'click\');\n}\n\n// Sim 9: Millimetre Scale\nfunction s9InitRuler() {\n    const ticksGroup = document.getElementById(\'s9MmTicks\');\n    if (!ticksGroup || ticksGroup.children.length > 0) return;\n\n    // 0 to 1 cm has 10 subdivisions (each 8px)\n    for (let i = 1; i <= 29; i++) {\n        if (i % 10 === 0) continue; // whole cm marks already drawn\n        const x = i * 8;\n        const isMid = i % 5 === 0;\n        const h = isMid ? 15 : 8;\n        const line = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');\n        line.setAttribute(\'x1\', x);\n        line.setAttribute(\'y1\', 0);\n        line.setAttribute(\'x2\', x);\n        line.setAttribute(\'y2\', h);\n        line.setAttribute(\'stroke\', isMid ? \'#fbbf24\' : \'#94a3b8\');\n        line.setAttribute(\'stroke-width\', isMid ? \'2\' : \'1\');\n        ticksGroup.appendChild(line);\n    }\n}\n\nfunction s9SetMm(val) {\n    const mm = parseInt(val, 10);\n    const arrow = document.getElementById(\'s9ArrowGroup\');\n    const arrowText = document.getElementById(\'s9ArrowText\');\n    const sliderVal = document.getElementById(\'s9SliderVal\');\n    const readout = document.getElementById(\'s9MmReadout\');\n\n    const x = mm * 8;\n    if (arrow) arrow.setAttribute(\'transform\', `translate(${x}, 0)`);\n    if (arrowText) arrowText.textContent = `${mm} mm`;\n    if (sliderVal) sliderVal.textContent = `${mm} mm`;\n\n    const cm = Math.floor(mm / 10);\n    const rem = mm % 10;\n    if (readout) readout.textContent = `${mm} mm = ${cm} cm ${rem} mm (${(mm/10).toFixed(1)} cm)`;\n}\n\n// Sim 10: Seed Growth\nfunction s10SetDay(day, mm) {\n    const radicle = document.getElementById(\'s10Radicle\');\n    const tip = document.getElementById(\'s10Tip\');\n    const dimText = document.getElementById(\'s10DimText\');\n    const readout = document.getElementById(\'s10DayReadout\');\n\n    // y starts at 24. Day 1: y=18 (3mm); Day 2: y=10 (8mm); Day 3: y=-15 (15mm); Day 4: y=-40 (24mm)\n    const yMap = { 3: 20, 8: 10, 15: -15, 24: -40 };\n    const targetY = yMap[mm] || -15;\n\n    if (radicle) radicle.setAttribute(\'d\', `M 85,24 Q 75,10 75,${targetY}`);\n    if (tip) {\n        tip.setAttribute(\'cx\', \'75\');\n        tip.setAttribute(\'cy\', targetY);\n    }\n    if (dimText) {\n        dimText.setAttribute(\'y\', (24 + targetY) / 2);\n        dimText.textContent = `${mm} mm`;\n    }\n\n    const cm = Math.floor(mm / 10);\n    const rem = mm % 10;\n    const mixed = cm > 0 ? `${cm} cm ${rem} mm` : `${mm} mm`;\n    if (readout) readout.textContent = `Day ${day}: ${mm} mm (${mixed})`;\n\n    playSound(\'click\');\n}\n\n// Sim 11: Precision Lines\nfunction s11Draw(mm, label) {\n    const line = document.getElementById(\'s11DrawnLine\');\n    const endTick = document.getElementById(\'s11EndTick\');\n    const pencil = document.getElementById(\'s11Pencil\');\n    const endText = document.getElementById(\'s11EndText\');\n    const readout = document.getElementById(\'s11LineReadout\');\n\n    // 10px is 0. Scale: 1mm = 3px.\n    const x = 10 + mm * 3;\n    if (line) line.setAttribute(\'x2\', x);\n    if (endTick) {\n        endTick.setAttribute(\'x1\', x);\n        endTick.setAttribute(\'x2\', x);\n    }\n    if (pencil) pencil.setAttribute(\'points\', `${x},10 ${x+10},-5 ${x+20},5`);\n    if (endText) {\n        endText.setAttribute(\'x\', x);\n        endText.textContent = label;\n    }\n    if (readout) readout.textContent = `Drawn Line: ${label} (${mm} mm)`;\n    playSound(\'correct\');\n}\n\n// Sim 14: Scaling Lengths\nfunction s14Update(val) {\n    const n = parseInt(val, 10);\n    const shirtsCount = document.getElementById(\'s14ShirtsCount\');\n    const totalCloth = document.getElementById(\'s14TotalCloth\');\n    const sliderVal = document.getElementById(\'s14SliderVal\');\n    const readout = document.getElementById(\'s14ScaleReadout\');\n\n    const totalCm = n * 225; // 2m 25cm = 225cm\n    const m = Math.floor(totalCm / 100);\n    const cm = totalCm % 100;\n\n    if (shirtsCount) shirtsCount.textContent = `${n} Shirts`;\n    if (totalCloth) totalCloth.textContent = `${m} m ${cm > 0 ? cm + \' cm\' : \'00 cm\'}`;\n    if (sliderVal) sliderVal.textContent = `${n} shirts`;\n    if (readout) readout.textContent = `${n} Shirts × (2 m 25 cm) = ${m} m ${cm > 0 ? cm + \' cm\' : \'\'}`;\n}\n\n// Sim 16: Feet and Inches\nfunction s16SetInches(val) {\n    const totalInches = parseInt(val, 10);\n    const ft = Math.floor(totalInches / 12);\n    const inc = totalInches % 12;\n\n    const cm = Math.round(totalInches * 2.54);\n    const sliderVal = document.getElementById(\'s16InchesVal\');\n    const readout = document.getElementById(\'s16DualHeightReadout\');\n    const cursor = document.getElementById(\'s16Cursor\');\n    const heightText = document.getElementById(\'s16HeightText\');\n\n    if (sliderVal) sliderVal.textContent = `${ft} ft ${inc} in`;\n    if (readout) readout.textContent = `${ft} ft ${inc} in ≈ ${cm} cm`;\n\n    // Map 36in (y=30) to 68in (y=-60)\n    const y = 30 - ((totalInches - 36) / 32) * 90;\n    if (cursor) {\n        cursor.setAttribute(\'y1\', y);\n        cursor.setAttribute(\'y2\', y);\n    }\n    if (heightText) {\n        heightText.setAttribute(\'y\', y - 7);\n        heightText.textContent = `${ft} ft ${inc} in (${cm} cm)`;\n    }\n}\n\n// Global initialization\nwindow.addEventListener(\'DOMContentLoaded\', () => {\n    initVoices();\n    if (\'speechSynthesis\' in window) {\n        window.speechSynthesis.onvoiceschanged = initVoices;\n    }\n    goToSlide(1);\n\n    // Keyboard navigation\n    window.addEventListener(\'keydown\', (e) => {\n        if (e.key === \'ArrowRight\') nextSlide();\n        else if (e.key === \'ArrowLeft\') prevSlide();\n        else if (e.key === \'Escape\') closeSolutionModal();\n    });\n});\n'
